defined( 'ABSPATH' ) || exit;

// Self-hosted updates - injected by EDD File Watermarking
add_action( 'init', function() {
	// Check if Extension Updater is available.
	if ( ! class_exists( 'PUM_Extension_Updater' ) ) {
		return;
	}

	// Get license from core's license service (if available).
	$license_key = '';
	if ( function_exists( '\PopupMaker\plugin' ) ) {
		$license_service = \PopupMaker\plugin( 'license' );
		if ( $license_service && method_exists( $license_service, 'get_license_key' ) ) {
			$license_key = $license_service->get_license_key();
		}
	}

	// Initialize updater (license can be empty for core).
	new \PUM_Extension_Updater(
		'https://wppopupmaker.com/edd-sl/',
		__FILE__,
		[
			'version'   => function_exists( 'popup_maker_config' ) ? popup_maker_config( 'version' ) : '',
			'license'   => $license_key, // Can be empty for core plugin
			'item_name' => 'Popup Maker',
			'item_id'   => 482276, // Core plugin EDD ID
			'author'    => 'Code Atlantic',
			'beta'      => false,
		]
	);
}, 11 ); // After core loads at 11
